/**
 * Types for Local Human Pose Detection Service.
 *
 * The activity types mirror activity-recognition/activity_types.py. tests/poseContract.test.ts compares
 * them with REAL backend output (tests/fixtures/*.json, generated by the Python service), so a change on
 * one side that is not made on the other fails a test.
 */

export interface PoseKeypoint {
  id: number;
  name: string;
  x: number;
  y: number;
  confidence: number;
  visible: boolean;
}

export interface PoseBoundingBox {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  width: number;
  height: number;
}

// --------------------------------------------------------------------------- activity recognition

/** Everything the service may call a person's activity. The last three say why NO activity is claimed. */
export const ACTIVITY_LABELS = [
  'Standing',
  'Sitting',
  'Walking',
  'Running',
  'Bending',
  'Lying Down',
  'Prolonged Inactivity',
  'Possible Sleeping',
  'Raising Hands',
  'Arm Movement',
  'Upper Body Bending',
  'Upper Body Inactivity',
  'Partial Body Detected',
  'Insufficient Visibility',
  'Unknown Activity',
] as const;
export type ActivityLabel = (typeof ACTIVITY_LABELS)[number];

/** How much of the body can be trusted: decides which activities may be classified at all. */
export const VISIBILITY_MODES = ['full_body', 'upper_body', 'partial', 'insufficient'] as const;
export type VisibilityMode = (typeof VISIBILITY_MODES)[number];

export const DETECTION_QUALITIES = ['good', 'medium', 'poor', 'insufficient'] as const;
export type DetectionQuality = (typeof DETECTION_QUALITIES)[number];

/** `untracked`: the frame was analysed alone (no history). `reacquired`: matched again after being missing. */
export const TRACKING_STATUSES = ['untracked', 'initializing', 'tracking', 'reacquired'] as const;
export type TrackingStatus = (typeof TRACKING_STATUSES)[number];

/** The fields of PoseActivity, in the order the service sends them. */
export const ACTIVITY_FIELDS = [
  'track_id',
  'label',
  'confidence',
  'confirmed',
  'candidate_label',
  'previous_label',
  'duration_s',
  'body_visibility',
  'visibility_mode',
  'detection_quality',
  'quality_score',
  'tracking_status',
  'observations',
  'inactive_s',
  'note',
  'missing_regions',
  'evidence',
] as const;

export interface PoseActivity {
  /** Stable id of this person across frames (not the per-frame detection index). Null when untracked. */
  track_id: number | null;
  /** What is shown. For `confirmed: false` it is the provisional candidate. */
  label: ActivityLabel;
  /**
   * 0..1 heuristic score (NOT a calibrated probability). Null when nothing is classified
   * (partial / insufficient visibility, unknown activity): no confidence is ever invented.
   */
  confidence: number | null;
  /** True once the activity held for the minimum number of frames and the minimum duration. */
  confirmed: boolean;
  /** What this single frame suggests, before temporal confirmation. */
  candidate_label: ActivityLabel;
  previous_label: ActivityLabel | null;
  /** Seconds in the shown activity (since the first frame that suggested it). */
  duration_s: number;
  /** 0..1 weighted share of reliable keypoints ("Body Visibility"). */
  body_visibility: number;
  visibility_mode: VisibilityMode;
  detection_quality: DetectionQuality;
  quality_score: number;
  tracking_status: TrackingStatus;
  /** How many frames of this person have been analysed. */
  observations: number;
  /** Seconds without movement while lying. Null for any other activity. */
  inactive_s: number | null;
  /** A human-readable explanation (why nothing is classified, or a caveat). */
  note: string | null;
  /** Body regions with no reliable keypoint: head, shoulders, arms, hips, legs. */
  missing_regions: string[];
  /** The numbers behind the decision (angles, speeds, ...). For diagnostics only. */
  evidence: Record<string, unknown>;
}

export interface LostTrack {
  track_id: number;
  last_label: ActivityLabel | null;
  seconds_since_seen: number;
}

export interface ActivityRecognitionInfo {
  enabled: boolean;
  tracking?: boolean;
  session_id?: string;
  persons_analyzed?: number;
  persons_skipped?: number;
  lost_tracks?: LostTrack[];
  /** Set when the activity layer failed: the pose result is still valid. */
  error?: string;
}

// --------------------------------------------------------------------------- pose

export interface PosePerson {
  /** Index of the detection in THIS frame only. Use `track_id` for identity over time. */
  person_id: number;
  /** Stable identity across frames; null/absent when the person was not tracked or activity is off. */
  track_id?: number | null;
  bbox: PoseBoundingBox;
  bbox_confidence: number;
  keypoints: PoseKeypoint[];
  visible_keypoints: number;
  total_keypoints: number;
  /** Absent/null when activity recognition is off, failed, or this person was not analysed. */
  activity?: PoseActivity | null;
}

export interface PoseDetectionResult {
  ok: boolean;
  person_count: number;
  persons: PosePerson[];
  image_width: number;
  image_height: number;
  inference_time_ms: number;
  total_time_ms: number;
  device: string;
  model: string;
  activity_recognition?: ActivityRecognitionInfo;
  /** Skeleton overlay as base64 JPEG, only when requested with `includeAnnotated`. */
  annotated_image_base64?: string;
}

export interface PoseServiceHealth {
  ok: boolean;
  status: string;
  uptime_seconds: number;
  service: string;
  hardware: {
    device: string;
    cuda_available: boolean;
    gpu_name: string | null;
    vram_allocated_mb: number | null;
    vram_total_mb: number | null;
  };
  model: {
    name: string;
    loaded: boolean;
    load_duration_ms: number;
    warmup_duration_ms: number;
  };
  activity_recognition?: {
    enabled: boolean;
    active_sessions?: number;
    tracked_people?: number;
  };
}
